def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    total_opp_d = sum(1 for _, o in history if o == 'D')
    total_opp_c = n - total_opp_d
    total_my_d = sum(1 for m, _ in history if m == 'D')

    if n >= 99:
        return 'D'

    if total_opp_c == 0 and n >= 5:
        return 'D'

    my_last, opp_last = history[-1]

    recent = history[-8:] if n >= 8 else history
    recent_opp_d = sum(1 for _, o in recent if o == 'D')
    opp_rate = total_opp_d / n
    my_rate = total_my_d / n

    tolerated = 0
    punished = 0
    for i in range(n - 1):
        if history[i][0] == 'D':
            next_opp = history[i + 1][1]
            if next_opp == 'C':
                tolerated += 1
            else:
                punished += 1

    if total_my_d == 0 and recent_opp_d == 0 and opp_rate <= 0.07 and n >= 93 and rng.random() < 0.4:
        return 'D'

    if punished == 0 and tolerated >= 1 and recent_opp_d == 0 and opp_rate <= 0.10 and n >= 95:
        return 'D'

    if total_opp_d == 0:
        return 'C'

    if n <= 4:
        return 'C'

    if opp_last == 'C':
        return 'C'

    if n >= 2 and history[-2][1] == 'D' and opp_last == 'D':
        return 'D'

    if opp_rate <= 0.15 and my_rate <= 0.2:
        return 'C'

    if opp_rate <= 0.35:
        return 'D' if rng.random() < 0.5 else 'C'

    if opp_rate < 0.6:
        return 'D'

    return 'D' if rng.random() < 0.85 else 'C'
